import numpy as np
A=acts(X)
for s in ['h1','h2','h3','h4']:
    v=A[s]
    print(s, "pairwise slopes:")
    for i in range(4):
        for j in range(i+1,4):
            m=(v[:,i]>1e-9)|(v[:,j]>1e-9)
            r=v[m,j]/np.maximum(v[m,i],1e-12)
            print("  ",i,j,"corr",round(np.corrcoef(v[:,i],v[:,j])[0,1],3),"slope mean",round(r[m.values].mean() if hasattr(m,'values') else r.mean(),3),"sd",round(r.std(),3))
